<?php
require_once __DIR__.'/../includes/marketplace.php';
$user=require_login('admin');
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$providerId=(int)($_POST['provider_id']??0);$status=$_POST['status']??'';if($providerId<1||!in_array($status,['pending','verified','trusted','preferred','rejected'],true)){set_flash('danger','Invalid provider update.');redirect('/admin/providers.php');}$stmt=db()->prepare('UPDATE providers SET verification_status=? WHERE id=?');$stmt->bind_param('si',$status,$providerId);$stmt->execute();$stmt=db()->prepare('SELECT user_id FROM providers WHERE id=?');$stmt->bind_param('i',$providerId);$stmt->execute();$owner=$stmt->get_result()->fetch_assoc();if($owner){$title='Provider verification updated';$message='Your provider verification status is now '.str_replace('_',' ',$status).'.';$stmt=db()->prepare('INSERT INTO notifications (user_id,type,title,message) VALUES (? ,\'provider_verification\',?,?)');$stmt->bind_param('iss',$owner['user_id'],$title,$message);$stmt->execute();}set_flash('success','Provider verification updated.');redirect('/admin/providers.php');}
$stmt=db()->prepare('SELECT p.*,u.first_name,u.last_name,u.email,u.status AS user_status FROM providers p INNER JOIN users u ON u.id=p.user_id ORDER BY FIELD(p.verification_status,\'pending\',\'verified\',\'trusted\',\'preferred\',\'rejected\'),p.namvoy_score DESC,p.created_at DESC');$stmt->execute();$providers=$stmt->get_result();
$page_title='Provider Verification';require __DIR__.'/../includes/header.php';
?><div class="container py-5"><div class="mb-4"><h1 class="h3 mb-1">Provider Verification</h1><p class="text-secondary mb-0">Review providers using verification status and operating performance.</p></div><div class="card"><div class="card-body"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Provider</th><th>Contact</th><th>NamVoy Score</th><th>Performance</th><th>Verification</th><th>Action</th></tr></thead><tbody><?php while($p=$providers->fetch_assoc()):?><tr><td><strong><?=e($p['business_name'])?></strong><br><small class="text-secondary"><?=e(trim($p['first_name'].' '.$p['last_name']))?></small></td><td><?=e($p['email'])?></td><td><span class="badge text-bg-dark"><?=number_format((float)$p['namvoy_score'],1)?></span></td><td>★ <?=number_format((float)$p['rating'],1)?> · Response <?=number_format((float)$p['response_rate'],0)?>%<br><small>Cancellation <?=number_format((float)$p['cancellation_rate'],0)?>% · Completed <?=number_format((int)$p['completed_bookings'])?></small></td><td><span class="badge text-bg-light"><?=e($p['verification_status'])?></span></td><td><form method="post" class="d-flex gap-2"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="provider_id" value="<?=$p['id']?>"><select name="status" class="form-select form-select-sm"><option value="pending">Pending</option><option value="verified">Verified</option><option value="trusted">Trusted</option><option value="preferred">Preferred</option><option value="rejected">Rejected</option></select><button class="btn btn-sm btn-dark">Save</button></form></td></tr><?php endwhile;?></tbody></table></div></div></div></div><?php require __DIR__.'/../includes/footer.php'; ?>